-- Fictional data for the local demo database.
-- IDs are generated by the database sequences.

WITH new_customer AS (
INSERT INTO accounts (
    username,
    password,
    email,
    phonenumber,
    age,
    address,
    city
)
VALUES (
    'Spyros',
    'demo-only',
    'spys@gmail.com',
    '6900000000',
    24,
    'Demo Street 1',
    'Athens'
    )
    RETURNING id
    ),

    new_store_category AS (
INSERT INTO store_categories (categoryname)
VALUES ('Demo Food')
    RETURNING id
    ),

    new_product_category AS (
INSERT INTO product_categories (description)
VALUES ('Demo Meals')
    RETURNING id
    ),

    new_store AS (
INSERT INTO stores (
    name,
    storecategory_id
)
SELECT
    'Demo Souvlaki',
    id
FROM new_store_category
    RETURNING id
    ),

    new_products AS (
INSERT INTO products (
    serial,
    productname,
    price,
    productcategory_id,
    store_id
)
SELECT
    sample.serial,
    sample.productname,
    sample.price,
    category.id,
    store.id
FROM (
    VALUES
    ('DEMO-GYROS', 'Chicken Gyros', 3.50),
    ('DEMO-FRIES', 'French Fries', 2.50)
    ) AS sample(serial, productname, price)
    CROSS JOIN new_product_category AS category
    CROSS JOIN new_store AS store
    RETURNING id, serial, price
    ),

    new_order AS (
INSERT INTO orders (
    account_id,
    store_id,
    submitdate,
    paymentmethod,
    cost
)
SELECT
    customer.id,
    store.id,
    LOCALTIMESTAMP,
    'CASH',
    9.50
FROM new_customer AS customer
    CROSS JOIN new_store AS store
    RETURNING id
    )

INSERT INTO items (
    product_id,
    quantity,
    price,
    order_id
)
SELECT
    product.id,
    CASE
        WHEN product.serial = 'DEMO-GYROS' THEN 2
        ELSE 1
        END,
    product.price,
    placed_order.id
FROM new_products AS product
         CROSS JOIN new_order AS placed_order;